USE retainiq;
DROP TABLE IF EXISTS dim_churn_detail,dim_account,dim_services,dim_location,dim_demographics,fact_customer_status;
CREATE TABLE fact_customer_status (customer_id VARCHAR(20) NOT NULL,tenure_months SMALLINT NOT NULL,monthly_charge DECIMAL(12,2) NOT NULL,total_charges DECIMAL(14,2) NOT NULL,total_refunds DECIMAL(14,2) NOT NULL,total_revenue DECIMAL(14,2) NOT NULL,satisfaction_score TINYINT NOT NULL,churn_score TINYINT NOT NULL,cltv INT NOT NULL,churn_label VARCHAR(10) NOT NULL,customer_status VARCHAR(30) NOT NULL,PRIMARY KEY(customer_id)) ENGINE=InnoDB;
CREATE TABLE dim_demographics (customer_id VARCHAR(20) NOT NULL PRIMARY KEY,gender VARCHAR(20),age SMALLINT,under_30 VARCHAR(10),senior_citizen VARCHAR(10),married VARCHAR(10),dependents VARCHAR(10),number_of_dependents SMALLINT,FOREIGN KEY(customer_id) REFERENCES fact_customer_status(customer_id)) ENGINE=InnoDB;
CREATE TABLE dim_location (customer_id VARCHAR(20) NOT NULL PRIMARY KEY,country VARCHAR(100),state VARCHAR(100),city VARCHAR(150),zip_code INT,latitude DECIMAL(9,6),longitude DECIMAL(9,6),population INT,FOREIGN KEY(customer_id) REFERENCES fact_customer_status(customer_id)) ENGINE=InnoDB;
CREATE TABLE dim_services (customer_id VARCHAR(20) NOT NULL PRIMARY KEY,phone_service VARCHAR(20),multiple_lines VARCHAR(30),internet_service VARCHAR(20),internet_type VARCHAR(40),online_security VARCHAR(20),online_backup VARCHAR(20),device_protection_plan VARCHAR(30),premium_tech_support VARCHAR(30),streaming_tv VARCHAR(20),streaming_movies VARCHAR(20),streaming_music VARCHAR(20),unlimited_data VARCHAR(20),avg_monthly_long_distance_charges DECIMAL(12,2),avg_monthly_gb_download INT,FOREIGN KEY(customer_id) REFERENCES fact_customer_status(customer_id)) ENGINE=InnoDB;
CREATE TABLE dim_account (customer_id VARCHAR(20) NOT NULL PRIMARY KEY,quarter VARCHAR(20),referred_a_friend VARCHAR(10),number_of_referrals INT,offer VARCHAR(100),contract VARCHAR(30),paperless_billing VARCHAR(20),payment_method VARCHAR(50),total_extra_data_charges DECIMAL(14,2),total_long_distance_charges DECIMAL(14,2),FOREIGN KEY(customer_id) REFERENCES fact_customer_status(customer_id)) ENGINE=InnoDB;
CREATE TABLE dim_churn_detail (customer_id VARCHAR(20) NOT NULL PRIMARY KEY,churn_category VARCHAR(100),churn_reason VARCHAR(200),FOREIGN KEY(customer_id) REFERENCES fact_customer_status(customer_id)) ENGINE=InnoDB;
